insert into app.site_memberships values('94000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000003','clinician',true);
insert into app.intake_sites(site_id,slug,enabled) values('94000000-0000-4000-8000-000000000003','automatic-test',true);
select set_config('request.jwt.claims','{}',true);
set local role service_role;
select set_config('test.entry',api.patient_start('automatic-test')::text,true);
