reset role;set local role anon;
select is(api.demo_action('consent',current_setting('test.eid')::uuid,current_setting('test.cap'),'{"accepted":true,"noticeVersion":"gi-privacy-2026-09-26"}')->>'ok','true','automatic evidence accepts the versioned new notice');
select is(api.demo_action('save',current_setting('test.eid')::uuid,current_setting('test.cap'),'{"version":0,"intake":{"name":"Fictional automatic patient","age":40,"sex":"Male","suppliedBy":"patient","enteredBy":"patient","relationship":"","stage":5,"answers":{}}}')->>'ok','true','fictional intake saved');
select is(api.demo_action('report_add',current_setting('test.eid')::uuid,current_setting('test.cap'),'{"name":"fictional-ultrasound.pdf","mime":"application/pdf","body":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","fields":[],"quality":"pending"}')->>'ok','true','first automatic report accepted');
select is(api.demo_action('report_add',current_setting('test.eid')::uuid,current_setting('test.cap'),'{"name":"fictional-ct.pdf","mime":"application/pdf","body":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","fields":[],"quality":"pending"}')->>'ok','true','second automatic report accepted');
select is(api.demo_action('submit',current_setting('test.eid')::uuid,current_setting('test.cap'))->>'ok','true','submit while reports are pending is allowed');
