select set_config('test.r1',(select id::text from phi.demo_reports where encounter_id=current_setting('test.eid')::uuid and name='fictional-ultrasound.pdf'),true);
select set_config('test.r2',(select id::text from phi.demo_reports where encounter_id=current_setting('test.eid')::uuid and name='fictional-ct.pdf'),true);
select set_config('test.version',(select version::text from phi.encounters where id=current_setting('test.eid')::uuid),true);
select set_config('test.initialjob',(select id::text from phi.demo_jobs where encounter_id=current_setting('test.eid')::uuid and source_version=current_setting('test.version')::int),true);
update phi.encounters set clinician_draft='{"impression":"Saved fictional draft","plan":"Review","specialty":"Gastroenterology","urgency":"review"}',draft_source_version=version where id=current_setting('test.eid')::uuid;
