select is(api.demo_worker('claim',current_setting('test.initialjob')::uuid)->'data','null'::jsonb,'assessment waits for pending reports');
select set_config('test.lease',api.report_worker('claim',current_setting('test.r1')::uuid)->'data'->>'lease',true);
select set_config('test.validfield','{"id":"p1-f1","label":"Printed observation","value":"Fictional observation","unit":"","page":1,"sourceText":"Fictional observation","date":"2026-09-01","reportType":"ultrasound","confidence":"text-extracted","verified":false}',true);
select is(api.report_worker('complete',current_setting('test.r1')::uuid,current_setting('test.lease')::uuid,
 jsonb_build_object('fields',jsonb_build_array(current_setting('test.validfield')::jsonb||bad.patch),'quality','Available'))->>'ok','false','worker rejects malformed automatic field: '||bad.label)
 from (values ('page zero','{"page":0}'::jsonb),('fractional page','{"page":1.5}'),('missing label','{"label":null}'),('oversized label',jsonb_build_object('label',repeat('x',121))),('unsupported type','{"reportType":"invented"}'),('string verification','{"verified":"false"}'),('nonstring source','{"sourceText":5}')) bad(label,patch);
select is(api.report_worker('complete',current_setting('test.r1')::uuid,current_setting('test.lease')::uuid,jsonb_build_object('fields',jsonb_build_array(current_setting('test.validfield')::jsonb)))->>'ok','false','worker rejects missing extraction quality');
select is(api.report_worker('complete',current_setting('test.r1')::uuid,current_setting('test.lease')::uuid,jsonb_build_object('fields',jsonb_build_array(current_setting('test.validfield')::jsonb),'quality',''))->>'ok','false','worker rejects empty extraction quality');
select is(api.report_worker('complete',current_setting('test.r1')::uuid,current_setting('test.lease')::uuid,'{"fields":[{"id":"p1-f1","label":"Printed observation","value":"Fictional observation","unit":"","page":1,"sourceText":"Fictional observation","date":"2026-09-01","reportType":"ultrasound","confidence":"text-extracted","verified":true}],"quality":"Available","provider":"gemini","promptVersion":"test"}')->>'ok','true','machine extraction publishes without staff action');
reset role;
select is((select version from phi.encounters where id=current_setting('test.eid')::uuid),current_setting('test.version')::int+1,'completed report advances submitted source version');
select is((select status from phi.demo_jobs where id=current_setting('test.initialjob')::uuid),'cancelled','older pending assessment is cancelled');
select is((select clinician_draft->>'impression' from phi.encounters where id=current_setting('test.eid')::uuid),'Saved fictional draft','automatic evidence never erases authored draft');
select is((select draft_source_version from phi.encounters where id=current_setting('test.eid')::uuid),current_setting('test.version')::int,'retained draft stays linked to the old facts');
select set_config('test.nextjob',(select id::text from phi.demo_jobs where encounter_id=current_setting('test.eid')::uuid and status='queued'),true);
select is((select r->>'name' from phi.demo_jobs j cross join lateral jsonb_array_elements(j.snapshot->'reports') r where j.id=current_setting('test.nextjob')::uuid and r->>'id'=current_setting('test.r1')),'fictional-ultrasound.pdf','job snapshot retains document name');
select is((select r->'fields'->0->>'verified' from phi.demo_jobs j cross join lateral jsonb_array_elements(j.snapshot->'reports') r where j.id=current_setting('test.nextjob')::uuid and r->>'id'=current_setting('test.r1')),'false','automatic evidence is never falsely staff verified');
set local role service_role;
select is(api.demo_worker('claim',current_setting('test.nextjob')::uuid)->'data','null'::jsonb,'second pending report also blocks an incomplete snapshot');
select set_config('test.lease',api.report_worker('claim',current_setting('test.r2')::uuid)->'data'->>'lease',true);
select is(api.report_worker('fail',current_setting('test.r2')::uuid,current_setting('test.lease')::uuid,null,'invalid_output')->>'ok','true','report failure is terminal and explicit');
