select set_config('test.currentjob',(select id::text from phi.demo_jobs where encounter_id=current_setting('test.eid')::uuid and status='queued'),true);
select is((select r->>'extractionStatus' from phi.demo_jobs j cross join lateral jsonb_array_elements(j.snapshot->'reports') r where j.id=current_setting('test.currentjob')::uuid and r->>'id'=current_setting('test.r2')),'failed','replacement snapshot records failure as unknown evidence');
set local role service_role;
select set_config('test.claim',api.demo_worker('claim',current_setting('test.currentjob')::uuid)::text,true);
select is(current_setting('test.claim')::jsonb->>'ok','true','assessment can run after all reports reach terminal states');
select is((select r->'fields'->0->>'reportType' from jsonb_array_elements(current_setting('test.claim')::jsonb->'data'->'reports') r where r->>'id'=current_setting('test.r1')),'ultrasound','claimed job carries type-aware report finding without staff verification');
reset role;
select set_config('request.jwt.claims','{"sub":"94000000-0000-4000-8000-000000000001","session_id":"94000000-0000-4000-8000-000000000002","aal":"aal2","role":"authenticated"}',true);
