select is(api.begin_staff_session()->>'ok','true','staff correction session starts');
select is(api.demo_action('report_verify',current_setting('test.eid')::uuid,null,jsonb_build_object('reportId',current_setting('test.r1'),'sourceVersion',current_setting('test.currentversion')::int,'fields',jsonb_build_array(current_setting('test.validfield')::jsonb||bad.patch)))->>'ok','false','direct staff RPC rejects malformed correction: '||bad.label)
 from (values ('page zero','{"page":0}'::jsonb),('missing label','{"label":null}'),('unsupported type','{"reportType":"invented"}'),('string verification','{"verified":"false"}')) bad(label,patch);
select is(api.demo_action('report_verify',current_setting('test.eid')::uuid,null,jsonb_build_object('reportId',current_setting('test.r1'),'sourceVersion',current_setting('test.currentversion')::int,'fields','[{"id":"p1-f1","label":"Printed observation","value":"Corrected fictional observation","unit":"","page":1,"sourceText":"Corrected fictional observation","date":"2026-09-01","reportType":"ultrasound","confidence":"text-extracted","verified":true}]'::jsonb))->>'ok','true','staff may optionally correct source evidence');
