select is((select fields->0->>'confidence' from phi.demo_reports where id=current_setting('test.r1')::uuid),'manual-transcription','staff edit cannot masquerade as untouched machine extraction');
select is((select clinician_draft->>'impression' from phi.encounters where id=current_setting('test.eid')::uuid),'Saved fictional draft','optional report corrections also preserve authored draft');
