select ok(exists(select 1 from audit.audit_events where action='demo_report_worker_complete' and record_ids=array[current_setting('test.eid')::uuid] and outcome='allowed'),'automatic report publication is audited');
select throws_ok(format('update phi.demo_jobs set snapshot=''{}'' where id=%L',current_setting('test.currentjob')),'P0001','Job source is immutable','old snapshots remain immutable');
-- Simulate a clinician release during an already claimed report extraction.
update phi.demo_reports set extraction_status='queued',extraction_attempts=0 where id=current_setting('test.r2')::uuid;
set local role service_role;
select set_config('test.lease',api.report_worker('claim',current_setting('test.r2')::uuid)->'data'->>'lease',true);
reset role;
update phi.encounters set released_at=now() where id=current_setting('test.eid')::uuid;
select set_config('test.releasedversion',(select version::text from phi.encounters where id=current_setting('test.eid')::uuid),true);
set local role service_role;
select is(api.report_worker('complete',current_setting('test.r2')::uuid,current_setting('test.lease')::uuid,'{"fields":[],"quality":"Empty"}')->>'ok','false','report cannot change a released plan');
reset role;
select is((select version::text from phi.encounters where id=current_setting('test.eid')::uuid),current_setting('test.releasedversion'),'released source version remains unchanged');
-- Intake-stage extraction must not stale patient answer autosaves. Submission freezes it.
select set_config('request.jwt.claims','{}',true);
set local role service_role;
select set_config('test.entry2',api.patient_start('automatic-test')::text,true);
select set_config('test.eid2',current_setting('test.entry2')::jsonb->'data'->>'id',true);
select set_config('test.cap2',current_setting('test.entry2')::jsonb->'data'->>'token',true);
reset role;set local role anon;
select api.demo_action('consent',current_setting('test.eid2')::uuid,current_setting('test.cap2'),'{"accepted":true,"noticeVersion":"gi-privacy-2026-09-22"}');
select api.demo_action('save',current_setting('test.eid2')::uuid,current_setting('test.cap2'),'{"version":0,"intake":{"name":"Fictional intake-stage patient","age":40,"sex":"Male","suppliedBy":"patient","enteredBy":"patient","relationship":"","stage":5,"answers":{}}}');
select api.demo_action('report_add',current_setting('test.eid2')::uuid,current_setting('test.cap2'),'{"name":"fictional-mri.pdf","mime":"application/pdf","body":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","fields":[],"quality":"pending"}');
reset role;
select set_config('test.r3',(select id::text from phi.demo_reports where encounter_id=current_setting('test.eid2')::uuid),true);
select set_config('test.intakeversion',(select version::text from phi.encounters where id=current_setting('test.eid2')::uuid),true);
set local role service_role;
select set_config('test.lease',api.report_worker('claim',current_setting('test.r3')::uuid)->'data'->>'lease',true);
select is(api.report_worker('complete',current_setting('test.r3')::uuid,current_setting('test.lease')::uuid,jsonb_build_object('fields',jsonb_build_array(current_setting('test.validfield')::jsonb||'{"reportType":"mri"}'::jsonb),'quality','Available'))->>'ok','true','extraction completes while questionnaire is still in progress');
reset role;
select is((select version::text from phi.encounters where id=current_setting('test.eid2')::uuid),current_setting('test.intakeversion'),'background extraction does not conflict with patient autosave');
set local role anon;
select is(api.demo_action('submit',current_setting('test.eid2')::uuid,current_setting('test.cap2'))->>'ok','true','intake-stage findings submit without staff intervention');
reset role;
select is((select snapshot->'reports'->0->'fields'->0->>'reportType' from phi.demo_jobs where encounter_id=current_setting('test.eid2')::uuid),'mri','submission snapshot already contains completed machine findings');
