select set_config('test.eid3',current_setting('test.entry3')::jsonb->'data'->>'id',true);
select set_config('test.cap3',current_setting('test.entry3')::jsonb->'data'->>'token',true);
reset role;set local role anon;
select api.demo_action('consent',current_setting('test.eid3')::uuid,current_setting('test.cap3'),'{"accepted":true,"noticeVersion":"gi-privacy-2026-09-22"}');
select api.demo_action('save',current_setting('test.eid3')::uuid,current_setting('test.cap3'),'{"version":0,"intake":{"name":"Fictional partial patient","age":40,"sex":"Male","suppliedBy":"patient","enteredBy":"patient","relationship":"","stage":5,"answers":{}}}');
select api.demo_action('report_add',current_setting('test.eid3')::uuid,current_setting('test.cap3'),'{"name":"fictional-blood.pdf","mime":"application/pdf","body":"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","fields":[],"quality":"pending"}');
reset role;
select set_config('test.r4',(select id::text from phi.demo_reports where encounter_id=current_setting('test.eid3')::uuid),true);
select set_config('request.jwt.claims','{"sub":"94000000-0000-4000-8000-000000000001","session_id":"94000000-0000-4000-8000-000000000002","aal":"aal2","role":"authenticated"}',true);
set local role authenticated;
select is(api.demo_action('review_partial',current_setting('test.eid3')::uuid)->>'ok','true','clinician explicitly takes partial intake for human review');
