select is(api.report_worker('complete',current_setting('test.r4')::uuid,current_setting('test.lease')::uuid,jsonb_build_object('fields',jsonb_build_array(current_setting('test.validfield')::jsonb||'{"reportType":"blood-test"}'::jsonb),'quality','Available'))->>'ok','true','report still processes during partial review');
