select is((select count(*)::int from phi.demo_jobs where encounter_id=current_setting('test.eid3')::uuid),0,'report completion does not introduce AI for an unsubmitted partial intake');
select is((select clinician_draft->>'impression' from phi.encounters where id=current_setting('test.eid3')::uuid),'Partial-review draft','partial-review draft survives new evidence');
select ok((select draft_source_version<version from phi.encounters where id=current_setting('test.eid3')::uuid),'partial-review draft is explicitly linked to older evidence');
select * from finish();
